import { readFileSync } from "node:fs";
import { join } from "node:path";
import { describe, expect, it } from "vitest";
import { importChatGptExport, type Conversation } from "../index";

// Generated by `node scripts/generate-sample-export.mjs`. Entirely synthetic.
const SAMPLE = join(process.cwd(), "test-fixtures", "chatgpt-sample.zip");

async function loadSample(): Promise<Conversation[]> {
  const result = await importChatGptExport(new Uint8Array(readFileSync(SAMPLE)));
  if (!result.ok) throw new Error(result.error.message);
  expect(result.warnings).toEqual([]);
  return result.conversations;
}

const byTitle = (convs: Conversation[], title: string) => {
  const conv = convs.find((c) => c.title === title);
  if (!conv) throw new Error(`missing conversation: ${title}`);
  return conv;
};

const textOf = (conv: Conversation) =>
  conv.messages.flatMap((m) => m.parts.map((p) => ("text" in p ? p.text : "")));

describe("test-fixtures/chatgpt-sample.zip", () => {
  it("imports all conversations with ids, titles and timestamps", async () => {
    const convs = await loadSample();
    expect(convs).toHaveLength(6);
    for (const c of convs) {
      expect(c.id).toMatch(/^c0nv/);
      expect(c.title).not.toBe("Untitled conversation");
      expect(c.createTime).toBeGreaterThan(0);
      expect(c.updateTime).toBeGreaterThan(c.createTime ?? 0);
      expect(c.messages.filter((m) => m.role === "user").length).toBeGreaterThanOrEqual(2);
      expect(c.messages.filter((m) => m.role === "assistant").length).toBeGreaterThanOrEqual(2);
      expect(c.messages[0]).toMatchObject({ role: "system", hidden: true });
    }
  });

  it("selects the current branch in the branched conversation", async () => {
    const conv = byTitle(await loadSample(), "Weekend trip ideas");
    const texts = textOf(conv);
    expect(texts).toContain("Can you make it cheaper and suitable for a rainy weekend?");
    expect(texts.some((t) => t.startsWith("Rainy-day budget plan"))).toBe(true);
    expect(texts).not.toContain("Can you make it cheaper?");
    expect(texts.some((t) => t.startsWith("For rain on a budget"))).toBe(false);
  });

  it("parses code, execution output and tool messages", async () => {
    const conv = byTitle(await loadSample(), "Fix CSV parser skipping rows");
    const kinds = conv.messages.flatMap((m) => m.parts.map((p) => p.kind));
    expect(kinds).toContain("code");
    expect(kinds).toContain("execution_output");
    expect(conv.messages.find((m) => m.role === "tool")?.authorName).toBe("python");
    expect(textOf(conv).some((t) => t.includes("```python"))).toBe(true);
  });

  it("parses image uploads and reasoning content", async () => {
    const convs = await loadSample();
    const recipeKinds = byTitle(convs, "Weeknight lentil soup").messages.flatMap((m) => m.parts.map((p) => p.kind));
    expect(recipeKinds).toContain("image");
    const tcpKinds = byTitle(convs, "How does a TCP handshake work?").messages.flatMap((m) => m.parts.map((p) => p.kind));
    expect(tcpKinds.filter((k) => k === "reasoning")).toHaveLength(2);
    expect(tcpKinds).not.toContain("unsupported");
  });
});
